write_file {"content":"const stats = require('./stats');

// Test mean
const meanTests = [
  { input: [1, 2, 3], expected: 2, desc: 'mean odd length' },
  { input: [1, 2, 3, 4], expected: 2.5, desc: 'mean even length' },
];

// Test mode
const modeTests = [
  { input: [1, 2, 3], expected: 1, desc: 'mode odd length' },
  { input: [1, 1, 2, 2], expected: 1, desc: 'mode even length (tie, smallest)' },
];

// Test median
const medianTests = [
  { input: [1, 2, 3], expected: 2, desc: 'median odd length' },
  { input: [1, 2, 3, 4], expected: 2.5, desc: 'median even length' },
];

// Test that input arrays are not modified
const noModificationTests = [
  { input: [1, 2, 3], desc: 'mean does not modify input' },
  { input: [1, 2, 3, 4], desc: 'median does not modify input' },
  { input: [1, 2, 3], desc: 'mode does not modify input' },
];

// Run tests
let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`✓ ${name}`);
    passed++;
  } catch (e) {
    console.log(`✗ ${name}: ${e.message}`);
    failed++;
  }
}

// Test mean
meanTests.forEach(({ input, expected, desc }) => {
  const original = [...input];
  test(desc, () => {
    const result = stats.mean(input);
    if (Math.abs(result - expected) > 0.0001) {
      throw new Error(`Expected ${expected}, got ${result}`);
    }
  });
});

// Test mode
modeTests.forEach(({ input, expected, desc }) => {
  const original = [...input];
  test(desc, () => {
    const result = stats.mode(input);
    if (result !== expected) {
      throw new Error(`Expected ${expected}, got ${result}`);
    }
  });
});

// Test median
medianTests.forEach(({ input, expected, desc }) => {
  const original = [...input];
  test(desc, () => {
    const result = stats.median(input);
    if (Math.abs(result - expected) > 0.0001) {
      throw new Error(`Expected ${expected}, got ${result}`);
    }
  });
});

// Test no modification
noModificationTests.forEach(({ input, desc }) => {
  test(desc, () => {
    const original = [...input];
    stats.mean(input);
    stats.median(input);
    stats.mode(input);
    for (let i = 0; i < input.length; i++) {
      if (input[i] !== original[i]) {
        throw new Error('Input array was modified');
      }
    }
  });
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
